import csv
from collections import defaultdict

rev = {
 'F3_Z01_cool':'5b98cbc1-fd25-5d8c-a96e-c3de49819174',
 'F3_Z01_heat':'b7f22e0c-833d-5373-87e1-51e1cb26f038',
 'F1_Z01_heat':'7a9e6dea-7214-57d7-a3ab-6fec741ab22a',
}
# Actually load all setpoint series for F3_Z01 and compare
sp_cool='5b98cbc1-fd25-5d8c-a96e-c3de49819174'
sp_heat='b7f22e0c-833d-5373-87e1-51e1cb26f038'
d=defaultdict(dict)
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        if row['timeseries_id'] in (sp_cool,sp_heat):
            d[row['timeseries_id']][row['timestamp']]=float(row['value'])
def month(ts): return ts[0:7]
for name,sid in [('cool',sp_cool),('heat',sp_heat)]:
    m=defaultdict(list)
    for ts,v in d[sid].items(): m[month(ts)].append(v)
    print('F3_Z01',name,{k:round(sum(v)/len(v),2) for k,v in sorted(m.items())})
